import type { Metadata } from 'next';
import { routeByPath, SITE_URL } from '@/lib/routes';

const ROUTE = '/services/research-impact/scientific-news-report/';
const meta = routeByPath.get(ROUTE)!;

export const metadata: Metadata = {
  title: meta.title,
  description: meta.description,
  alternates: { canonical: SITE_URL + ROUTE },
  openGraph: {
    title: meta.title,
    description: meta.description,
    url: SITE_URL + ROUTE,
    type: 'website',
    images: ["https://pubrica.com/share/pubrica-card.jpg"],
  },
};

const schema = [{"@context":"https://schema.org","@type":"Service","name":"Scientific news report","serviceType":"Research impact service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/research-impact/scientific-news-report/","description":"Your manuscript turned into a press release a science journalist can actually use. Your manuscript, turned into a story somebody would run.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"How does a news report help visibility and citations?","acceptedAnswer":{"@type":"Answer","text":"It translates technical findings into a narrative that can be promoted through institutional channels, media platforms and public networks, which improves discoverability and uptake by non-specialists and practitioners.\n\nWhat it cannot do is guarantee coverage. That depends on the finding, the news cycle and who else published that week. A good release makes your paper usable by a journalist; it does not make it a story."}},{"@type":"Question","name":"Are the reports compliant with journal and institutional policies?","acceptedAnswer":{"@type":"Answer","text":"Yes. Reports follow journal-specific media policies, COPE guidance and embargo terms, and the tone and format can be adjusted to your journal or media team’s requirements.\n\nThe embargo is the part to get right. It differs by journal, some permit press offices to distribute early under embargo and some do not, and breaching it can cost the publication."}},{"@type":"Question","name":"Can our communications office work with you directly?","acceptedAnswer":{"@type":"Answer","text":"Yes, and it works better that way. We support collaborative workflows where a media team pre-approves drafts, requests cross-departmental summaries and receives press-ready formats.\n\nBulk orders and funded-project summaries can be handled under an MoU, which is usually the sensible arrangement for a university producing these regularly."}},{"@type":"Question","name":"What role do these play in policy or guideline work?","acceptedAnswer":{"@type":"Answer","text":"A condensed report lets policymakers, hospital administrators and clinical leaders take in the key findings of a high-impact study without reading the manuscript, which supports evidence translation into guidelines and decisions.\n\nA policy-facing version leads on the resource implication and on what would have to be true for the finding to change practice. That is a different document from a public one."}},{"@type":"Question","name":"Why would a journal or publisher outsource this?","acceptedAnswer":{"@type":"Answer","text":"Because producing accurate research highlights, lay summaries and media releases at volume is editorial work that competes with everything else an editorial office has to do.\n\nIt also separates the release from the people who accepted the paper, which is a reasonable thing to want."}},{"@type":"Question","name":"Can it be used for grant reporting and dissemination plans?","acceptedAnswer":{"@type":"Answer","text":"Yes. Output can be aligned with funder expectations — Horizon Europe, NIH and DBT India among others — that require non-technical summaries or dissemination evidence.\n\nReports can be included in final project reports, data management plans or media deliverables. Tell us at the start if that is the purpose, because it changes the structure."}},{"@type":"Question","name":"Do you offer other languages?","acceptedAnswer":{"@type":"Answer","text":"Yes — Spanish, Mandarin, Arabic, French, Tamil and others, culturally localised rather than translated word for word.\n\nA release translated literally reads as translated, which undermines the point. What changes between versions is idiom, framing and sometimes what leads."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Research impact","item":"https://pubrica.com/services/research-impact/scientific-news-report/"}]}];

